// Package alarms holds the operating system's scheduler for scheduled
// Scouts: launchd on macOS, systemd on Linux and Task Scheduler on Windows
// (ADR-0027 §7).
//
// Each adapter lists, writes and removes the entries JobPilot owns, which
// it recognises by name. Which entries should exist is decided in core,
// which compares the fingerprint each entry carries with the alarm it
// wants; an adapter never decides anything.
//
// The file each adapter writes is generated by plain code, tested on every
// platform. Only running launchctl, systemctl or schtasks is the platform's.
package alarms

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"regexp"
	"strings"

	"github.com/google/uuid"
)

// fingerprintMarker precedes the fingerprint in every entry JobPilot
// writes, so List can read it back without parsing the whole format.
const fingerprintMarker = "jobpilot-fingerprint: "

var fingerprintPattern = regexp.MustCompile(regexp.QuoteMeta(fingerprintMarker) + `([0-9a-f]+)`)

// readFingerprint finds the fingerprint an entry was written with, or ""
// for one written by something else.
func readFingerprint(content []byte) string {
	match := fingerprintPattern.FindSubmatch(content)
	if match == nil {
		return ""
	}
	return string(match[1])
}

// checkScoutID refuses anything but a UUID before it is written into a
// plist, a unit file or task XML, or used in a file name.
func checkScoutID(id string) error {
	if _, err := uuid.Parse(id); err != nil {
		return fmt.Errorf("a scout's alarm needs a scout ID that is a UUID, got %q", id)
	}
	return nil
}

// runner runs a program and returns its combined output.
type runner func(ctx context.Context, name string, args ...string) ([]byte, error)

// runCommand runs a program for real. Its error carries the program's own
// words, since those are what a user or a bug report needs.
func runCommand(ctx context.Context, name string, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, name, args...)
	hideWindow(cmd)
	var out bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &out
	if err := cmd.Run(); err != nil {
		said := strings.TrimSpace(out.String())
		if said == "" {
			return out.Bytes(), fmt.Errorf("%s %s: %w", name, strings.Join(args, " "), err)
		}
		return out.Bytes(), fmt.Errorf("%s %s: %w: %s", name, strings.Join(args, " "), err, said)
	}
	return out.Bytes(), nil
}

// wakeArgs is what every alarm runs the daemon with.
func wakeArgs(scoutID string) []string {
	return []string{"scout", "wake", scoutID}
}
